bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 30
docker exec -i "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
try{
 const res=await pool.query(`SELECT r.*,l.seller_user_id,l.title,l.price_stars,l.status listing_status,l.paid_video_file_id,
 l.thumbnail_file_id,l.sample_file_id,l.sample_duration_seconds,l.rights_verified,l.adult_consent_verified,
 l.fee_terms_accepted_at,l.management_fee_bps,l.fee_policy_id
 FROM videobot_post_receipts r JOIN videobot_listings l USING(listing_id)
 WHERE r.delivery_key IN
 (SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid')`);
 const paid=(await pool.query("SELECT COUNT(DISTINCT buyer_user_id)::int AS buyers,COUNT(*)::int AS payments FROM videobot_stars_ledger WHERE kind='paid'")).rows[0];
 const all=(await pool.query("SELECT COUNT(*)::int AS n FROM videobot_post_receipts WHERE status='sent'")).rows[0];
 const o=(await pool.query("SELECT COUNT(*)::int AS n FROM videobot_video_invoice_orders WHERE telegram_payment_charge_id IS NOT NULL")).rows[0];
 const cols=(await pool.query("SELECT column_name FROM information_schema.columns WHERE table_name='videobot_listings' AND table_schema='public'")).rows.map(r=>r.column_name);
 if(res.rows.length!==1)process.exit(31);
 let code=0;
 const row=res.rows[0];
 if(paid.buyers===1)code|=1;
 if(paid.payments>0)code|=2;
 if(all.n===1)code|=4;
 if(all.n>1)code|=8;
 if(o.n===0)code|=16;
 if(row.rights_verified===true&&row.adult_consent_verified===true)code|=32;
 if(row.fee_terms_accepted_at!=null&&Number(row.management_fee_bps)===3000)code|=64;
 if(row.paid_video_file_id&&row.sample_file_id&&row.thumbnail_file_id&&Number(row.sample_duration_seconds)<=30&&row.sample_file_id!==row.paid_video_file_id)code|=128;
 process.exitCode=code;
}finally{await pool.end()}
NODE
